/* cache: 'reload' skips the browser's own short-term copies, so a new version is never saved with files from the last one */
self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(FILES.map(f => new Request(f, { cache: 'reload' })))).then(() => self.skipWaiting()));
});
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k.startsWith('study-buddy-') && k !== CACHE).map(k => caches.delete(k)))).then(() => self.clients.claim()));
});
self.addEventListener('message', e => { if (e.data === 'version' && e.source) e.source.postMessage({ version: VERSION }); });
/* Use the network when it's there (so updates show up), and the saved copy when it isn't.
   'no-cache' asks the server whether a file changed (a quick "not modified" when it hasn't). A slow connection falls back
   to the saved copy after 4 seconds. Only page loads fall back to the home page; a missing script gets a plain error. */
self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET' || new URL(req.url).origin !== location.origin) return;
  const saved = () => caches.match(req, { ignoreSearch: true }).then(m => m || (req.mode === 'navigate' ? caches.match('./index.html') : Response.error()));
  if (req.headers.has('range')) {                                   // audio asks for byte ranges: answer from the saved file when there is one
    e.respondWith(caches.match(req, { ignoreSearch: true }).then(m => m ? rangeOf(m, req.headers.get('range')) : fetch(req)));
    return;
  }
  e.respondWith(new Promise(resolve => {
    let done = false; const finish = r => { if (!done) { done = true; resolve(r); } };
    const timer = setTimeout(() => saved().then(m => { if (m && m.type !== 'error') finish(m); }), 4000);
    fetch(req.mode === 'navigate' ? req : new Request(req, { cache: 'no-cache' })).then(res => {
      clearTimeout(timer);
      if (res.ok && res.status === 200) { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)); }
      finish(res);
    }).catch(() => { clearTimeout(timer); saved().then(finish); });
  }));
});
async function rangeOf(res, range) {
  const buf = await res.arrayBuffer(), m = /bytes=(\d*)-(\d*)/.exec(range || '');
  if (!m) return new Response(buf, { status: 200, headers: res.headers });
  const start = m[1] ? +m[1] : 0, end = m[2] ? Math.min(+m[2], buf.byteLength - 1) : buf.byteLength - 1;
  return new Response(buf.slice(start, end + 1), { status: 206, headers: { 'Content-Type': res.headers.get('Content-Type') || 'application/octet-stream', 'Content-Range': `bytes ${start}-${end}/${buf.byteLength}`, 'Content-Length': String(end - start + 1), 'Accept-Ranges': 'bytes' } });
}
